insert into kb_articles (id, title, body) values
  ('KB-01', 'Password reset link expired', 'Reset links are valid for 30 minutes and only the most recent link works. Ask the user to request a new link and open it within 30 minutes, in a private browser window. If many users at one company are affected at once, escalate to engineering as a possible incident.'),
  ('KB-02', 'Unlocking a locked-out user', 'After 5 failed attempts an account is locked for 15 minutes. An admin can unlock it immediately under Settings > Users > select user > Unlock account.'),
  ('KB-03', 'Two-factor (SMS) codes not arriving', 'Check that the phone number includes the country code (+31 for the Netherlands). Users can switch to an authenticator app under Profile > Security. If several users are affected, escalate: it may be an SMS provider issue.'),
  ('KB-04', 'Roles and permissions', 'The Manager role does not include Finance access by default. Admins can add it under Settings > Roles > Manager > Permissions > Finance (view).'),
  ('KB-05', 'Setting up SSO (Azure AD / Entra ID)', 'SSO is available on the Enterprise plan. The customer''s IT team needs to create an Enterprise Application in Azure, then share the Metadata URL. Admin enters it under Settings > Security > Single sign-on. Test with one user before enforcing SSO for everyone.'),
  ('KB-06', 'Duplicate charges and refunds', 'Duplicate card charges are usually a pending authorisation that disappears within 5 working days. If both are settled, support can issue a refund from the billing console. Refunds take 5 to 10 working days.'),
  ('KB-07', 'VAT on invoices', 'Dutch customers are charged 21% VAT. If 0% appears, the account''s billing country or VAT number is wrong. Correct it under Billing > Company details; support can reissue the invoice.'),
  ('KB-08', 'Cancelling a subscription', 'Admins cancel under Billing > Subscription > Cancel. Access continues until the end of the paid period. No refunds for partial months.'),
  ('KB-09', 'Adding users and pricing', 'Add users under Settings > Users > Invite. Each extra user costs EUR 9 per month (Starter), EUR 15 (Business) or according to contract (Enterprise).'),
  ('KB-10', 'Changing the billing email', 'Admins can change the invoice recipient under Billing > Company details > Invoice email.'),
  ('KB-11', 'Exporting data', 'Most lists have an Export button (top right) that downloads CSV, which opens in Excel. Large exports are emailed when ready.'),
  ('KB-12', 'Deleting projects', 'Archive a project under Project > Settings > Archive. Permanent deletion is possible after archiving and cannot be undone.'),
  ('KB-13', 'CSV import missing rows', 'Rows are skipped when required fields (SKU, name, price) are empty or duplicate SKUs exist. Download the import log under Imports > History to see skipped rows.'),
  ('KB-14', 'API errors and rate limits', 'Rate limit: 100 requests per minute per API key. HTTP 429 means the limit is reached; use batching and retry with backoff. HTTP 500 errors are server-side: collect request IDs and timestamps and escalate to engineering.'),
  ('KB-15', 'Webhooks not delivering', 'Webhooks are disabled automatically after 20 consecutive failed deliveries. Check Settings > Developers > Webhooks for the status and re-enable after fixing the endpoint.'),
  ('KB-16', 'Performance issues', 'Slow dashboards and search are often caused by very large date ranges or filters. Ask for the account, page, time of day and a browser HAR file, then escalate to engineering with details.'),
  ('KB-17', 'Calendar sync duplicates', 'Duplicates occur when the calendar is connected twice. Disconnect all calendars under Integrations > Calendar, then reconnect once.'),
  ('KB-18', 'Integrations available', 'Native integrations: Google Calendar, Outlook, Exact Online, Mollie, Zapier. Mailchimp is available through Zapier.'),
  ('KB-19', 'Security and compliance documents', 'The SOC 2 Type II report and security questionnaire answers are shared by the account manager under NDA. Route these requests to the Account team.'),
  ('KB-20', 'GDPR deletion requests', 'Admins can delete a person''s data under Customers > select customer > Delete personal data. Deletion is completed within 30 days, within the GDPR deadline. Support can confirm completion in writing.'),
  ('KB-21', 'Suspicious logins', 'Treat as a security incident. Advise the admin to reset passwords for affected accounts and enforce two-factor login immediately. Escalate to the Security team right away.'),
  ('KB-22', 'Outages', 'Check status.cloudnest.example. For a full outage affecting a customer, escalate immediately as a P1 incident and update the customer every 30 minutes.')
insert into sample_tickets (id, customer, plan, subject, body, expected_category, expected_priority) values
  ('T-001', 'Brightwell Retail', 'Enterprise', 'Cannot log in after password reset', 'Since this morning none of our 40 users can log in. The reset email arrives but the link says expired. Our store teams are blocked.', 'Access & Login', 'P1'),
  ('T-002', 'Kavo Dental', 'Starter', 'Invoice charged twice', 'We were charged twice for October (two payments of 49 euro on our card). Please refund one.', 'Billing', 'P2'),
  ('T-003', 'Nordline Logistics', 'Business', 'Dashboard very slow', 'The shipments dashboard takes more than 30 seconds to load since last week. It used to be instant.', 'Performance', 'P2'),
  ('T-004', 'Studio Vela', 'Starter', 'How do I export my data to Excel?', 'I want to export the customer list to Excel for my accountant. Where is that option?', 'How-to', 'P4'),
  ('T-005', 'Mercator Finance', 'Enterprise', 'API returning 500 errors', 'Our nightly sync via the REST API fails with HTTP 500 on the /orders endpoint since 02:00. Production reporting for the board is affected.', 'Integration', 'P1'),
  ('T-006', 'Green Leaf Cafe', 'Starter', 'Add dark mode please', 'Would love a dark mode for the app, my staff use it in the evening.', 'Feature request', 'P4'),
  ('T-007', 'Brightwell Retail', 'Enterprise', 'SSO setup with Azure AD', 'We want to connect single sign-on with Azure AD. Can you share the steps and what we need from our IT team?', 'How-to', 'P3'),
  ('T-008', 'Hollands Bouw', 'Business', 'Wrong VAT on invoice', 'Our invoice shows 0% VAT but we are a Dutch company and need 21% for our bookkeeping. Please correct the invoice.', 'Billing', 'P3'),
  ('T-009', 'Nordline Logistics', 'Business', 'Report shows wrong totals', 'The monthly revenue report shows 12,400 but the sum of the individual orders is 13,150. Which number is right?', 'Bug', 'P2'),
  ('T-010', 'Kavo Dental', 'Starter', 'User locked out', 'One of my assistants entered the wrong password too many times and is now locked out. How do I unlock her?', 'Access & Login', 'P3'),
  ('T-011', 'Mercator Finance', 'Enterprise', 'Webhook not firing', 'The order.created webhook stopped sending events to our endpoint yesterday. Nothing changed on our side.', 'Integration', 'P2'),
  ('T-012', 'Studio Vela', 'Starter', 'Cancel subscription', 'I want to cancel my subscription at the end of this month. How do I do that?', 'Billing', 'P3'),
  ('T-013', 'Pier 9 Events', 'Business', 'Calendar sync duplicates', 'Every event now appears twice in our Google Calendar after syncing.', 'Bug', 'P3'),
  ('T-014', 'Hollands Bouw', 'Business', 'Can we add more users?', 'We are hiring 5 people. How do we add users and what does it cost?', 'Billing', 'P4'),
  ('T-015', 'Brightwell Retail', 'Enterprise', 'Data missing after import', 'We imported 2,000 products from CSV yesterday. Only 1,400 appear. No error message was shown.', 'Bug', 'P2'),
  ('T-016', 'Green Leaf Cafe', 'Starter', 'App crashes on iPad', 'The app closes immediately when I open the orders screen on my iPad. iPhone works fine.', 'Bug', 'P3'),
  ('T-017', 'Mercator Finance', 'Enterprise', 'Security questionnaire', 'Our compliance team needs your SOC 2 report and answers to our vendor security questionnaire before renewal.', 'Account & Compliance', 'P3'),
  ('T-018', 'Pier 9 Events', 'Business', 'Slow search', 'Searching for a customer takes 10 to 15 seconds. We have about 50,000 customers.', 'Performance', 'P3'),
  ('T-019', 'Nordline Logistics', 'Business', 'Two-factor codes not arriving', 'Our users do not receive the SMS code for two-factor login. Some of them cannot work.', 'Access & Login', 'P2'),
  ('T-020', 'Kavo Dental', 'Starter', 'Change billing email', 'Please send invoices to finance@kavodental.example instead of my personal email.', 'Billing', 'P4'),
  ('T-021', 'Studio Vela', 'Starter', 'Integration with Mailchimp?', 'Do you integrate with Mailchimp so I can send newsletters to my customers?', 'Integration', 'P4'),
  ('T-022', 'Brightwell Retail', 'Enterprise', 'All stores offline', 'The platform is completely down for all our 12 stores. Error page on every screen. We are losing sales right now.', 'Outage', 'P1'),
  ('T-023', 'Hollands Bouw', 'Business', 'Delete a project', 'How can I permanently delete an old project and all its data?', 'How-to', 'P4'),
  ('T-024', 'Pier 9 Events', 'Business', 'Permission issue for manager', 'Our event manager cannot see the finance tab even though we gave her the Manager role.', 'Access & Login', 'P3'),
  ('T-025', 'Mercator Finance', 'Enterprise', 'GDPR data deletion request', 'A former customer requested deletion of all their personal data under GDPR. Please confirm how we do this within the legal deadline.', 'Account & Compliance', 'P2'),
  ('T-026', 'Green Leaf Cafe', 'Starter', 'Printer receipts cut off', 'The receipts from our printer cut off the last line with the total amount.', 'Bug', 'P3'),
  ('T-027', 'Nordline Logistics', 'Business', 'Rate limit errors on API', 'We receive HTTP 429 Too Many Requests when we sync more than 500 orders. What are the limits?', 'Integration', 'P3'),
  ('T-028', 'Studio Vela', 'Starter', 'Love the new update!', 'Just wanted to say the new invoice design looks great. Thanks!', 'Feedback', 'P4'),
  ('T-029', 'Brightwell Retail', 'Enterprise', 'Suspicious login alerts', 'We got alerts about logins from an unknown country on two admin accounts. Please help us check this urgently.', 'Security', 'P1'),
  ('T-030', 'Kavo Dental', 'Starter', 'Appointment reminders not sent', 'Patients did not receive their SMS reminders today. We had 4 no-shows.', 'Bug', 'P2')
